import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve, relative } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
export const REPO = resolve(__dirname, '..', '..');

/* The directories where an untracked file means an INCOMPLETE COMMIT rather than a stray
   scratch file. Everything here is either shipped or is the thing that verifies what
   ships; a scratchpad note or a local .env is deliberately out of scope. */
/* `docs` is here for one reason and it is not tidiness: `scripts/buildDoLines.js` READS
   `docs/do-lines-review.md`, and that file failing to ship is why every curated `do` line
   was missing from production. A doc the runtime or a build script resolves is a dependency
   whatever its extension. A doc nothing resolves is merely named below, never failed on. */
export const GUARDED = ['server/lib', 'server/routes', 'server/scripts', 'client/src', 'client/test', 'mobile/src', 'docs'];

const CODE = /\.(js|jsx|mjs|cjs|ts|tsx|json)$/;
// Docs count as referenceable because the server READS one: `scripts/buildDoLines.js`
// resolves `docs/do-lines-review.md`, and CLAUDE.md records that exact file failing to
// ship as the reason every curated `do` line was missing in production.
const REFERENCEABLE = /\.(js|jsx|mjs|cjs|ts|tsx|json|md)$/;

/* THE SUITE'S OWN FILES, found by pattern rather than by import.
   `npm test` is `node --test`, which walks for `*.test.js` — no import graph involved. The
   `client/test/*.mjs` suites are invoked by name from CLAUDE.md's Verifying section, and
   everything beside them (`browser.mjs`, `buildFixture.mjs`, the harnesses) is what makes
   them run, so the whole directory counts. Untracked here means: runs on this machine,
   cannot run on any other checkout. */
export const isSuiteFile = (f) => /\.test\.(js|mjs|cjs)$/.test(f) || /^client\/test\/[^/]+\.(mjs|jsx)$/.test(f);

const posix = (p) => p.split('\\').join('/');

const git = (args) => {
  try {
    return execFileSync('git', args, { cwd: REPO, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch {
    return '';
  }
};

const lines = (s) => s.split('\n').map((l) => l.trim()).filter(Boolean);

/** Files git has never been told about, inside the guarded directories. */
export function untrackedFiles() {
  return lines(git(['ls-files', '--others', '--exclude-standard']))
    .map(posix)
    .filter((f) => REFERENCEABLE.test(f) && GUARDED.some((d) => f.startsWith(`${d}/`)));
}

/**
 * Untracked files the SUITE would run, which nothing imports and no path literal names.
 * This is the case the guard missed: eighteen tests, discovered by pattern, invisible to
 * an import graph. A reference by discovery is still a reference.
 */
export function undiscoveredSuiteFiles() {
  return untrackedFiles().filter(isSuiteFile);
}

/**
 * Everything else untracked in a guarded directory. NOT a failure — whether an unreferenced
 * doc or scratch module belongs in a commit is a judgment about intent that static analysis
 * cannot make. Returned so the CLI can NAME them, because the bare count is what let a test
 * file slide past a human reading this output.
 */
export function unreferencedUntracked() {
  const dangling = new Set(danglingReferences({ mode: stagedFiles().length ? 'staged' : 'tree' }).map((b) => b.resolved));
  const suite = new Set(undiscoveredSuiteFiles());
  return untrackedFiles().filter((f) => !dangling.has(f) && !suite.has(f));
}

/** Files this commit would carry. */
export function stagedFiles() {
  return lines(git(['diff', '--cached', '--name-only', '--diff-filter=ACMR'])).map(posix);
}

/* Tracked source files, for the working-tree mode the test uses.

   DELIBERATELY NOT FILTERED BY `GUARDED`. That list says where an untracked file is a
   problem; it must not also decide what gets READ, and conflating the two put the single
   most important file out of scope. `server/index.js` sits in `server/`, matches none of
   the guarded prefixes, and is exactly the file that mounts a route — it imports
   `./routes/trips.js`, and the first draft of this guard did not look at it. deployBoundary
   makes the same distinction for the same reason: it scans `lib/`, `routes/` AND
   `index.js`. Scanning everything tracked is a few hundred files and cannot have this bug. */
export function trackedSources() {
  return lines(git(['ls-files'])).map(posix).filter((f) => CODE.test(f));
}

/* Relative specifiers only. A bare specifier is a package and resolves through node_modules;
   an absolute one cannot name a repo file portably. Path literals are included because the
   server reads JSON and KB files by path — the same shapes deployBoundary.test.js resolves. */
const SPECIFIER = /(?:from|import|require)\s*\(?\s*['"](\.[^'"]+)['"]/g;
const PATH_LITERAL = /['"](\.\.?\/[^'"]*\.(?:js|jsx|mjs|cjs|ts|tsx|json|md))['"]/g;

/* A BARE FILENAME IS A PATH TOO, and requiring a leading `./` hid every browser fixture.
   `join(__dirname, 'tripFixture.json')` is how all five harnesses reach their fixtures and
   `buildDoLines.js` reaches its markdown; none of them writes `./`. Resolved relative to
   the referencing file's own directory and only reported when it lands on a file git does
   not track, so a bare `'index.js'` in a comment cannot fire unless an untracked
   `index.js` really sits next to it. */
const BARE_LITERAL = /['"]([A-Za-z0-9_][A-Za-z0-9._-]*\.(?:js|jsx|mjs|cjs|ts|tsx|json|md))['"]/g;

/** Resolve a specifier the way node would, returning a repo-relative path or null. */
function resolveSpec(fromFile, spec) {
  const base = resolve(REPO, dirname(fromFile));
  const candidates = [
    resolve(base, spec),
    ...(CODE.test(spec) ? [] : ['.js', '.jsx', '.mjs', '.ts', '.tsx', '/index.js'].map((e) => resolve(base, spec + e))),
  ];
  for (const c of candidates) {
    const rel = posix(relative(REPO, c));
    if (rel.startsWith('..')) continue;
    if (existsSync(c) || REFERENCEABLE.test(rel)) return rel;
  }
  return null;
}

/**
 * Every reference, in `sources`, to a file git does not track.
 *
 * @param {object} [opts]
 * @param {'staged'|'tree'} [opts.mode='staged']
 * @returns {Array<{from:string, specifier:string, resolved:string}>}
 */
export function danglingReferences({ mode = 'staged' } = {}) {
  const untracked = new Set(untrackedFiles());
  if (!untracked.size) return [];

  const sources = (mode === 'staged' ? stagedFiles() : trackedSources()).filter((f) => CODE.test(f));
  const out = [];

  for (const f of sources) {
    // Read what the COMMIT carries, not what the working tree happens to hold — they differ
    // exactly when someone stages a partial change, which is when this matters most.
    let src = '';
    if (mode === 'staged') src = git(['show', `:${f}`]);
    if (!src) {
      const onDisk = join(REPO, f);
      if (!existsSync(onDisk)) continue;
      src = readFileSync(onDisk, 'utf8');
    }

    const seen = new Set();
    for (const re of [SPECIFIER, PATH_LITERAL, BARE_LITERAL]) {
      re.lastIndex = 0;
      let m;
      while ((m = re.exec(src))) {
        const spec = m[1];
        if (seen.has(spec)) continue;
        seen.add(spec);
        const resolved = resolveSpec(f, spec);
        if (resolved && untracked.has(resolved)) out.push({ from: f, specifier: spec, resolved });
      }
    }
  }
  return out;
}

/* ── CLI ── */
if (process.argv[1] && posix(process.argv[1]).endsWith('scripts/commitGuard.js')) {
  const staged = stagedFiles();
  const mode = staged.length ? 'staged' : 'tree';
  const bad = danglingReferences({ mode });
  const suite = undiscoveredSuiteFiles();
  const rest = unreferencedUntracked();

  console.log(`commitGuard: ${mode} mode · ${staged.length} staged · ${untrackedFiles().length} untracked in guarded dirs`);

  if (bad.length) {
    console.error(
      `\n${bad.length} REFERENCE${bad.length > 1 ? 'S' : ''} TO UNTRACKED FILE${bad.length > 1 ? 'S' : ''} — ` +
      `this commit would be green locally and incomplete on main:\n`
    );
    for (const b of bad) console.error(`  ${b.from}\n      references ${b.specifier}  ->  ${b.resolved}  (UNTRACKED)`);
  }

  if (suite.length) {
    console.error(
      `\n${suite.length} SUITE FILE${suite.length > 1 ? 'S' : ''} GIT DOES NOT TRACK — ` +
      `${suite.length > 1 ? 'these run' : 'this runs'} here and nowhere else:\n`
    );
    // Named as a discovery reference, because that is what it is. Nothing imports a test.
    for (const f of suite) console.error(`  ${f}  (found by the runner's own pattern, not by an import)`);
  }

  // NAMED, NEVER COUNTED. A bare count is what this output used to give, and it is what a
  // human reads straight past — which is exactly how eighteen tests stayed untracked.
  if (rest.length) {
    console.log(`\n${rest.length} untracked and unreferenced in a guarded dir. Not a failure; nothing resolves to`);
    console.log('them, so whether they belong in this commit is yours to say:\n');
    for (const f of rest) console.log(`  ${f}`);
  }

  const missing = [...new Set([...bad.map((b) => b.resolved), ...suite])];
  if (!missing.length) {
    console.log('\nnothing this commit carries references an untracked file, and no suite file is missing');
    process.exit(0);
  }
  console.error(`\n  git add ${missing.join(' ')}\n`);
  process.exit(1);
}
#!/usr/bin/env node
// Project the authored perimeter KB into counter_cards, and prove nothing was lost.
//
//   node scripts/migrateCounterCards.js --dry-run   report only, touches nothing
//   node scripts/migrateCounterCards.js             upsert every curated card
//
// THE KB IS THE SOURCE OF RECORD. This script re-derives every `source = 'curated'`
// row from kristy_perimeter_kb.json plus the reviewed `do` lines in
// docs/do-lines-review.md. It upserts on `slug`, so running it twice is the same as
// running it once, and editing the KB and re-running is the supported way to change a
// curated card. Generated cards are never touched.
//
// IT REFUSES TO REPORT SUCCESS WHILE ANYTHING IS UNPLACED. The summary/expanded split
// is a re-ranking of authored content, so every sentence the KB holds has to land
// somewhere on the card. Anything that does not is printed as a diff, by field, and
// the run exits non-zero.
//
// PICKS ARE NEVER MIGRATED. A `kind: 'pick'` entry is one sentence for a list row, not a
// card: it has no headline, no do line and no depth, and `counter_cards` has
// `headline text not null` and `check (kind in ('shelf','home'))`, so a pick can neither
// fit the row nor be read by anything that reads the table. It is skipped HERE, before
// projection, counted and printed — so the table-backed doors cannot leak one by
// construction, and so a pick never reaches `cardToRow` where it would fail the migration
// as a card with no action on it. The projection phase is a function so a test can feed
// a fixture pick through the identical path and watch it never arrive.

import { readFileSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';

import perimeterKb from '../kristy_perimeter_kb.json' with { type: 'json' };
import { isPick, questionEntries } from '../lib/perimeter.js';
import {
  TABLE,
  RETIRED,
  RETIRED_GENERATED,
  projectEntry,
  coverage,
  cardToRow,
  parseReviewTable,
} from '../lib/counterCards.js';
import { MAX_HEADLINE_WORDS } from '../lib/counterCardLint.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REVIEW_FILE = join(__dirname, '..', '..', 'docs', 'do-lines-review.md');

const words = (s) => (String(s || '').match(/[\w’'-]+/g) || []).length;

/* ── Project ──────────────────────────────────────────────────────────────── */

/**
 * Project every QUESTION entry into a card; set every pick aside.
 *
 * The one place the migration decides what becomes a row. `questionEntries` is the same
 * predicate every read door uses, so the set that reaches `projectEntry` — and from there
 * `cardToRow` — is the set a shopper can ask for, and nothing else.
 *
 * @param {Array} entries   the KB entries, picks included
 * @param {Map} reviewed    slug → { do, flag } from docs/do-lines-review.md
 * @returns {{ cards:Array, picks:Array, problems:object }}
 */
export function projectCorpus(entries, reviewed) {
  const picks = (entries || []).filter(isPick);
  const cards = [];
  const problems = { missingDo: [], unmapped: [], longHeadline: [], longDo: [], flagged: [] };

  for (const entry of questionEntries(entries || [])) {
    const review = reviewed.get(entry.id);
    const card = projectEntry(entry, { doLine: review?.do || '' });

    if (!card.do) problems.missingDo.push(entry.id);
    if (review?.flag && review.flag !== '—' && review.flag !== '-' && review.flag !== '') {
      problems.flagged.push(`${entry.id} — ${review.flag}`);
    }
    if (words(card.headline) > MAX_HEADLINE_WORDS) problems.longHeadline.push(`${entry.id} (${words(card.headline)}w)`);
    if (card.do && words(card.do) > 14) problems.longDo.push(`${entry.id} (${words(card.do)}w)`);

    const cov = coverage(entry, card);
    for (const u of cov.unmapped) problems.unmapped.push(`${entry.id} · ${u.field}: ${u.text.slice(0, 90)}`);

    cards.push(card);
  }

  return { cards, picks, problems };
}

/* ── Write ────────────────────────────────────────────────────────────────── */

// Both imported lazily so --dry-run works with no Supabase credentials at all: the report
// is the useful half during authoring, and it should never need a database.
//
// dotenv has to land BEFORE lib/supabase.js evaluates, or the client is built with no URL
// and every failure below reports as "apply the SQL first" when the real cause is a
// missing credential — a wrong diagnosis is worse than no diagnosis.
// The write phase is a function so it can RETURN an exit code rather than call
// process.exit() mid-flight. Killing the process while a Supabase fetch handle is still
// closing trips a libuv assertion on Windows and the shell sees 127 — which reads as
// "command not found" rather than "the migration refused to write".
async function write(cards) {
  await import('dotenv/config');
  const { supabase } = await import('../lib/supabase.js');

  if (!process.env.SUPABASE_URL || !process.env.SUPABASE_SERVICE_ROLE_KEY) {
    console.error('\n[counter-cards] SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY are not set.');
    console.error('[counter-cards] nothing was written. --dry-run needs no credentials.');
    return 1;
  }

  const rows = cards.map(cardToRow);

  // PREFLIGHT — a real select, never a head:true count. PostgREST answers 204 / null count
  // / no error for a table that does not exist, which reads as "present, empty"; a real
  // select against a missing table returns PGRST205 and says so.
  const { data: before, error: preErr } = await supabase.from(TABLE).select('slug');
  if (preErr) {
    console.error('[counter-cards] cannot read the table:', preErr.message);
    console.error('[counter-cards] apply supabase/counter_cards.sql first.');
    return 1;
  }
  const existing = new Set((before || []).map((r) => r.slug));

  const { error } = await supabase.from(TABLE).upsert(rows, { onConflict: 'slug' });
  if (error) {
    console.error('[counter-cards] upsert failed:', error.message);
    // 42P10 is Postgres saying ON CONFLICT (slug) has no unique index to infer from. It is
    // a LOUD failure, not a silent duplicate insert — but the index still has to be there,
    // and counter_cards_slug_key is what makes this script re-runnable at all.
    if (/42P10|no unique|exclusion constraint/i.test(error.message)) {
      console.error('[counter-cards] the unique index on slug is missing — counter_cards_slug_key.');
    }
    console.error('[counter-cards] has supabase/counter_cards.sql been applied?');
    return 1;
  }

  // ── Retirement, in the same run as the upsert ──
  // A folded card removed from the KB would otherwise keep answering from a row nobody can
  // edit any more, because the entry it was projected from is gone. Scoped to
  // source = 'curated' so a generated card can never be swept by a stale slug collision.
  if (RETIRED.length) {
    const { data: gone, error: delErr } = await supabase
      .from(TABLE)
      .delete()
      .in('slug', RETIRED)
      .eq('source', 'curated')
      .select('slug');
    if (delErr) {
      console.error('[counter-cards] retirement delete failed:', delErr.message);
      return 1;
    }
    const removed = (gone || []).map((r) => r.slug);
    console.log(
      `[counter-cards] retired ${RETIRED.length} curated slug(s); ${removed.length} row(s) deleted` +
        `${removed.length ? `: ${removed.join(', ')}` : ' (already absent)'}. ✓`
    );
  }

  // ── Generated retirement, scoped to source = 'generated' ──
  // Its own list and its own delete for the same reason the one above is scoped: neither
  // kind may ever sweep the other. A generated slug placed in RETIRED silently deletes
  // nothing — the row stays live and keeps answering — so the two cannot share a list.
  if (RETIRED_GENERATED.length) {
    const { data: gone, error: delErr } = await supabase
      .from(TABLE)
      .delete()
      .in('slug', RETIRED_GENERATED)
      .eq('source', 'generated')
      .select('slug');
    if (delErr) {
      console.error('[counter-cards] generated retirement delete failed:', delErr.message);
      return 1;
    }
    const removed = (gone || []).map((r) => r.slug);
    console.log(
      `[counter-cards] retired ${RETIRED_GENERATED.length} generated slug(s); ${removed.length} row(s) deleted` +
        `${removed.length ? `: ${removed.join(', ')}` : ' (already absent)'}. ✓`
    );
  }

  // ── Idempotency, accounted for rather than asserted ──
  // A second run must report 0 inserted and every card updated. If the unique index on
  // slug were missing the upsert would append instead of update and the row count would
  // climb — so the count IS the live proof of the constraint, checked by behaviour rather
  // than by reading a catalog PostgREST will not show us.
  const inserted = rows.filter((r) => !existing.has(r.slug)).length;
  const updated = rows.length - inserted;

  const { data: after, error: postErr } = await supabase.from(TABLE).select('slug');
  if (postErr) {
    console.error('[counter-cards] wrote, but could not verify:', postErr.message);
    return 1;
  }
  const total = (after || []).length;
  const distinct = new Set((after || []).map((r) => r.slug)).size;

  console.log(
    `[counter-cards] upserted ${rows.length} curated cards — ${inserted} inserted, ${updated} updated. ✓`
  );
  console.log(`[counter-cards] table now holds ${total} rows (${distinct} distinct slugs).`);

  if (total !== distinct) {
    console.error(
      `\n[counter-cards] DUPLICATE SLUGS: ${total} rows for ${distinct} slugs — ` +
        'the unique index on slug is missing and the upsert appended instead of updating.'
    );
    return 1;
  }
  return 0;
}

/* ── Run ──────────────────────────────────────────────────────────────────── */

async function main() {
  const DRY = process.argv.includes('--dry-run');

  // The reviewed do lines.
  let reviewed = new Map();
  try {
    reviewed = parseReviewTable(readFileSync(REVIEW_FILE, 'utf8'));
  } catch {
    console.error(`[counter-cards] no review file at ${REVIEW_FILE}`);
    console.error('[counter-cards] draft it first — the do line is authored, never derived.');
    return 1;
  }

  const entries = perimeterKb.entries || [];
  const { cards, picks, problems } = projectCorpus(entries, reviewed);

  // ── Report ──
  const line = (label, list) => {
    console.log(`\n${label}: ${list.length}`);
    for (const x of list) console.log(`  · ${x}`);
  };

  console.log(`[counter-cards] ${entries.length} authored entries → ${cards.length} cards`);
  console.log(`[counter-cards] ${picks.length} picks skipped, never migrated`);
  console.log(`[counter-cards] reviewed do lines found: ${reviewed.size}`);

  if (problems.unmapped.length) line('UNPLACED CONTENT (must be zero)', problems.unmapped);
  if (problems.missingDo.length) line('MISSING do LINE', problems.missingDo);
  if (problems.longHeadline.length) line(`HEADLINE OVER ${MAX_HEADLINE_WORDS} WORDS`, problems.longHeadline);
  if (problems.longDo.length) line('do LINE OVER 14 WORDS', problems.longDo);
  if (problems.flagged.length) line('FLAGGED IN REVIEW (not blocking)', problems.flagged);

  const blocking =
    problems.unmapped.length + problems.missingDo.length + problems.longHeadline.length + problems.longDo.length;

  if (blocking) {
    console.error(`\n[counter-cards] ${blocking} blocking problem(s) — nothing was written.`);
    return 1;
  }
  console.log('\n[counter-cards] every authored sentence is placed. ✓');

  if (DRY) {
    console.log('[counter-cards] --dry-run: nothing written.');
    return 0;
  }

  return write(cards);
}

// Run only when invoked as a script. Imported by a test, this file exposes `projectCorpus`
// and does nothing else — a migration that ran on import would write to the live table
// the moment a test file loaded it.
//
// Both sides are REAL paths. `import.meta.url` is already resolved through symlinks and
// `process.argv[1]` is whatever the shell typed, so comparing them raw would, through a
// symlinked checkout, decide "imported" and exit 0 having migrated nothing — a green
// status with no subject. The no-op is printed for the same reason: silent is the one
// thing a skipped migration may not be.
const invokedAs = (() => {
  try {
    return process.argv[1] ? realpathSync(resolve(process.argv[1])) : null;
  } catch {
    return null;
  }
})();
if (invokedAs === realpathSync(fileURLToPath(import.meta.url))) {
  process.exitCode = await main();
} else {
  console.log('[counter-cards] not run: imported, not invoked.');
}

