const VETO_WORDS = Object.values(MECHANICAL_VETO).flat();
const VETO_RE = new RegExp(`\\b(${VETO_WORDS.join('|')})(s|es|ing)?\\b`, 'i');

/** The first vetoed word in a line, or null. */
export function mechanicalVeto(line) {
  const m = String(line || '').match(VETO_RE);
  return m ? m[0] : null;
}

// The line's word bar. A card's do line is 14; a pick line has no headline above it to
// share the work with, so it gets two more and no more — past this it is a paragraph a
// shopper reads with one hand while holding the thing it describes.
export const MAX_PICK_WORDS = 16;

// A pick is a food, so it files under a counter. `label_terms` is a reference section, the
// same exclusion the list matcher applies at attach (NON_AISLE_SECTIONS in listMatch.js): a
// pick filed there could never reach a row and would be dead on arrival.
const NON_AISLE_SECTION = 'label_terms';

// Fields a pick may not carry. A pick with a headline or a depth field is a card that has
// dodged the card's bar by declaring itself something else — and a field on a pick that no
// surface renders is a claim nobody reviews. The list is every authored card field, plus
// the paid boundary's own list so a field added to the depth is forbidden here without a
// second edit. `sources` is the exception: it is a depth field on a card because it is
// PAID there, and it is REQUIRED on a pick because it is the only thing that separates an
// authored line from a remembered one. Nothing on a pick is served, so paid/free does not
// apply to it.
export const PICK_FORBIDDEN_FIELDS = new Set([
  'asked_as', 'headline', 'why', 'tier_note', 'look_for', 'watch_out', 'detail',
  'kristy_take', 'labels_decoded', 'cart_pick', 'short_answer', 'buying_tips', 'question',
  'evidence_tier', 'instead', 'card_why', 'eyebrow_short', 'pick_steps', 'science',
  ...DEPTH_FIELDS.filter((f) => f !== 'sources'),
]);

// Bare noun: lowercase, letters, spaces and hyphens, at most three words. An alias is
// matched by whole-phrase containment against what a shopper TYPES on a list, and a list
// says "carrots", never "how do I pick carrots".
const MAX_PICK_ALIAS_WORDS = 3;
const BARE_NOUN = /^[a-z][a-z\s-]*$/;

// The number pair, by a simple suffix relation and nothing cleverer: `s`, `es`, or `y` to
// `ies`. Not a stemmer. A shopper writes "carrots" and "carrot" both, and "cherries" and
// "cherry" both, and each has to hit; a stemmer would admit pairs no shopper types.
const PLURALS_OF = (a) => [
  `${a}s`,
  `${a}es`,
  a.endsWith('y') ? `${a.slice(0, -1)}ies` : null,
].filter(Boolean);

// Words that describe a food without naming one. A pick alias made only of these ("frozen",
// "organic") is a subject-less alias: the matcher walks aliases by containment, so it would
// attach the pick to any row carrying the word. Explicit list, widened deliberately.
const MODIFIER_WORDS = new Set([
  'frozen', 'canned', 'tinned', 'dried', 'dry', 'fresh',
  'organic', 'raw', 'whole', 'wild', 'farmed', 'pasteurized', 'unpasteurized',
]);
const onlyModifiers = (a) => a.split(/[\s-]+/).filter(Boolean).every((w) => MODIFIER_WORDS.has(w));

const hasUrl = (s) => /https?:\/\/\S+/.test(String(s || ''));

/**
 * Lint one pick entry. Empty is the passing state.
 * @returns {Array<{code:string, detail:string}>}
 */
// Zero first person (VOICE_SPEC). `I` is case-sensitive so "i" inside nothing trips;
// `us` is lowercase-only so a country of origin ("US grown") does not read as a pronoun.
const hasFirstPerson = (line) =>
  /\bI\b/.test(line) || /\b(me|my|mine|we|our|ours)\b/i.test(line) || /\bus\b/.test(line);

export function lintPick(entry) {
  const out = [];
  const fail = (code, detail) => out.push({ code, detail });
  const e = entry || {};

  // ── Required ──
  for (const f of ['id', 'title', 'category', 'decision']) {
    if (!String(e[f] || '').trim()) fail('PICK_FIELD_MISSING', `a pick needs ${f}`);
  }

  // ── Forbidden ──
  for (const f of Object.keys(e)) {
    if (PICK_FORBIDDEN_FIELDS.has(f)) {
      fail('PICK_FIELD_FORBIDDEN', `"${f}" is a card field — a pick is one sentence, not a card`);
    }
  }

  // ── The food, bare ──
  const title = String(e.title || '').trim();
  if (title && (words(title) > 4 || /[.!?,;:]/.test(title))) {
    fail('PICK_TITLE_NOT_BARE', `the title is the food, bare: "${title}"`);
  }

  // ── Filed under a counter ──
  const category = String(e.category || '').trim();
  if (category) {
    const section = sectionForCategory(category);
    if (!section) fail('PICK_CATEGORY_UNSECTIONED', `"${category}" maps to no counter section`);
    else if (section === NON_AISLE_SECTION) {
      fail('PICK_CATEGORY_NON_AISLE', `"${category}" files under ${section}, which no list row is ever sorted into`);
    }
  }

  // ── Aliases: bare nouns, both numbers ──
  const aliases = Array.isArray(e.aliases) ? e.aliases.map((a) => String(a || '').trim()).filter(Boolean) : [];
  if (aliases.length < 2) {
    fail('PICK_ALIASES_TOO_FEW', `a pick needs at least 2 bare-noun aliases; got ${aliases.length}`);
  }
  const notBare = aliases.filter((a) => !BARE_NOUN.test(a) || words(a) > MAX_PICK_ALIAS_WORDS);
  if (notBare.length) {
    fail(
      'PICK_ALIAS_NOT_BARE',
      `an alias is what a shopper types on a list — lowercase, ≤${MAX_PICK_ALIAS_WORDS} words: ${notBare.map((a) => `"${a}"`).join(', ')}`
    );
  }
  // A state-bearing pick ("Frozen peas") is about the frozen thing. `stateContradicts` is
  // silent when the ROW names no state, so a bare `peas` alias here would attach the frozen
  // line to a fresh row. Every alias carries the state, or the pick does not ship.
  if (title && statesIn(title).size) {
    const stateless = aliases.filter((a) => !statesIn(a).size);
    if (stateless.length) {
      fail(
        'PICK_ALIAS_DROPS_STATE',
        `the title names a state, so every alias must too: ${stateless.map((a) => `"${a}"`).join(', ')}`
      );
    }
  }
  const subjectless = aliases.filter(onlyModifiers);
  if (subjectless.length) {
    fail(
      'PICK_ALIAS_NO_SUBJECT',
      `an alias must name a food, not only describe one: ${subjectless.map((a) => `"${a}"`).join(', ')}`
    );
  }
  const set = new Set(aliases);
  const paired = aliases.some((a) => PLURALS_OF(a).some((p) => set.has(p)));
  if (aliases.length && !paired) {
    fail(
      'PICK_ALIASES_NO_NUMBER_PAIR',
      'aliases must carry a singular AND its plural (s / es / y→ies) — a list says "carrot" and "carrots" both'
    );
  }

  // ── The line ──
  const line = String(e.decision || '').trim();
  if (line) {
    // Exactly one sentence, closed with a period. Two sentences is a card's summary; a
    // fragment is a label.
    const terminals = (line.match(/[.!?](?=\s|$)/g) || []).length;
    if (terminals !== 1 || !line.endsWith('.')) {
      fail('PICK_LINE_NOT_ONE_SENTENCE', `exactly one sentence ending in a period: "${line}"`);
    }
    if (/\?/.test(line)) fail('PICK_LINE_QUESTION', `a pick states, it never asks: "${line}"`);
    if (words(line) > MAX_PICK_WORDS) {
      fail('PICK_LINE_TOO_LONG', `${words(line)}w > ${MAX_PICK_WORDS}: ${line}`);
    }
    if (hasFirstPerson(line)) {
      fail('PICK_LINE_FIRST_PERSON', `no I/me/my/we/our on any line Kristy speaks: "${line}"`);
    }
    if (/—/.test(line)) fail('PICK_LINE_EM_DASH', `no em-dash asides: "${line}"`);
    // No digits. A number is a measurement, and a measurement is a claim with a source a
    // list row cannot show. "Heavy for its size", never "over 200g".
    if (/\d/.test(line)) fail('PICK_LINE_DIGIT', `no digits on a pick line: "${line}"`);
    const vetoed = mechanicalVeto(line);
    if (vetoed) {
      fail(
        'PICK_LINE_NOT_MECHANICAL',
        `"${vetoed}" is about the body, not the food. A pick describes surface, weight, smell, ` +
          `color, firmness, date or a label word — what happens to the food, never to the shopper: "${line}"`
      );
    }
    // Same house copy as every other line.
    const brit = britishSpellings(line);
    if (brit.length) fail('COPY_BRITISH', `British spelling: ${brit.map((w) => `"${w}"`).join(', ')} — the corpus is American`);
    if (STRAIGHT_QUOTE.test(line)) fail('COPY_STRAIGHT_QUOTE', `a straight quote or apostrophe in: "${line}" — the corpus uses “ ” and ’`);
  }

  // ── Sources, each fetchable ──
  // A URL is the bar because a URL can be fetched, and "every source gets fetched before it
  // ships" is the rule. A source named from memory has no URL to give.
  const sources = Array.isArray(e.sources) ? e.sources : [];
  if (!sources.length) fail('PICK_SOURCES_MISSING', 'a pick needs at least one source, with a URL');
  const noUrl = sources.filter((s) => !(hasUrl(s) || hasUrl(s?.url)));
  if (noUrl.length) {
    fail('PICK_SOURCE_NO_URL', `every pick source carries a URL it was fetched from; ${noUrl.length} of ${sources.length} do not`);
  }

  return out;
}

/* ═══════════════════════════ Per-card ═══════════════════════════ */

/**
 * Lint one card — curated or generated — or one pick.
 * @returns {Array<{code:string, detail:string}>} empty when the card passes.
 */
export function lintCard(card) {
  // A pick is not a card and clears a different bar. Branching here rather than at the
  // call site means the generation path, the corpus tests and any future door all reach
  // the pick rules through the one function they already call.
  if (card?.kind === 'pick') return lintPick(card);

  const out = [];
  const fail = (code, detail) => out.push({ code, detail });

  const headline = String(card?.headline || '').trim();
  const doLine = String(card?.do ?? card?.do_line ?? '').trim();

  if (!headline) fail('HEADLINE_MISSING', 'the card has no verdict');
  else if (words(headline) > MAX_HEADLINE_WORDS) {
    fail('HEADLINE_TOO_LONG', `${words(headline)}w > ${MAX_HEADLINE_WORDS}: ${headline}`);
  }

  // ONE VERDICT PER HEADLINE. The fallback belongs in look_for or watch_out.
  for (const h of headlineHedge(headline)) {
    fail('HEADLINE_HEDGED', `${h.detail}. State the standard undiluted; move the fallback to watch_out`);
  }

  // Accuracy outranks firmness. A claim that needs a false mechanism is a wrong claim.
  for (const m of falseMechanisms(card)) {
    fail('CLAIM_FALSE_MECHANISM', m.why);
  }

  if (!doLine) {
    fail('DO_MISSING', 'the card has no physical action');
  } else {
    if (words(doLine) > MAX_DO_WORDS) {
      fail('DO_TOO_LONG', `${words(doLine)}w > ${MAX_DO_WORDS}: ${doLine}`);
    }
    const verb = firstToken(doLine);
    if (!IMPERATIVE_VERBS.has(verb)) {
      fail('DO_NOT_IMPERATIVE', `opens with "${verb}", which is not a known imperative verb`);
    }
  }

  // A GENERATED card must carry aliases, because aliases are the only way it can ever be
  // RETRIEVED again. The deterministic matcher scores alias phrases; a card with none
  // scores zero against every future question, so the next shopper asking the identical
  // thing regenerates it. That is not a cosmetic gap — it is an unbounded spend loop and
  // a corpus that forks into near-duplicates of the same answer.
  if (card?.source === 'generated') {
    const aliases = Array.isArray(card.aliases) ? card.aliases.filter((a) => String(a || '').trim()) : [];
    if (aliases.length < 2) {
      fail(
        'ALIASES_MISSING',
        `a generated card needs at least 2 aliases to be findable again; got ${aliases.length}`
      );
    }

    // AN ALIAS HAS TO BE SHORT, and this is not a style rule. The matcher looks for each
    // alias as a run of words INSIDE the question, so a full sentence never matches
    // anything: "how to tell if a cantaloupe is ripe" is not contained in "how do I pick a
    // good cantaloupe". The first generated card shipped six aliases, every one of them a
    // sentence, and it regenerated on every ask because none could ever hit.
    const longOnes = aliases.filter((a) => words(a) > MAX_ALIAS_WORDS);
    if (longOnes.length) {
      fail(
        'ALIASES_TOO_LONG',
        `an alias is matched as a phrase inside a question, so it must be short. Over ${MAX_ALIAS_WORDS} words: ${longOnes.map((a) => `"${a}"`).join(', ')}`
      );
    }
    if (!aliases.some((a) => words(a) <= 2)) {
      fail(
        'ALIASES_NO_SHORT_FORM',
        'at least one alias must be one or two words — usually the bare subject noun, which is the most likely hit'
      );
    }
  }

  // Copy hygiene, across every readable field. A card is one voice, so a British spelling
  // in watch_out is the same defect as one in the headline.
  const copy = [
    headline,
    doLine,
    card?.why,
    card?.tier_note,
    card?.topic,
    card?.eyebrow,
    card?.cta_item,
    card?.detail,
    card?.kristy_take,
    ...(card?.look_for || []),
    ...(card?.watch_out || []),
  ]
    .filter(Boolean)
    .map(String);

  const brit = [...new Set(copy.flatMap(britishSpellings))];
  if (brit.length) {
    fail('COPY_BRITISH', `British spelling: ${brit.map((w) => `"${w}"`).join(', ')} — the corpus is American`);
  }
  const straight = copy.filter((t) => STRAIGHT_QUOTE.test(t));
  if (straight.length) {
    fail(
      'COPY_STRAIGHT_QUOTE',
      `a straight quote or apostrophe in: "${straight[0].slice(0, 60)}…" — the corpus uses “ ” and ’`
    );
  }

  const tierNote = String(card?.tier_note || '').trim();
  if (!tierNote) {
    fail('TIER_NOTE_MISSING', 'the tier has no sentence carrying it on the free surface');
  } else if (echoesRubric(tierNote)) {
    fail(
      'TIER_NOTE_IS_RUBRIC',
      `the tier note repeats the rubric's definition instead of saying why THIS call carries this tier — "${tierNote.slice(0, 70)}…"`
    );
  }

  /* THE NOTE MAY NOT POINT AT THE TIER, because there is nothing to point at. The chip that
     named it was removed on 2026-08-04 (a classification rendered as a badge labels nothing),
     and `tier_note` took over its job on the free summary. Four curated cards — raw_milk,
     raw_kefir, raw_aged_cheese, sprouts_raw — shared one sentence reading "This tier is
     Kristy's sourcing standard", which the moment the chip went became a definite reference
     to a thing no longer on screen. Exactly the referent-less problem the chip had, inverted.

     They also slipped `TIER_NOTE_IS_RUBRIC`: near-paraphrases of the rubric rather than the
     rubric itself, and that check only catches the literal text. This one is structural. */
  if (tierNote && /\b(this|the)\s+tier\b/i.test(tierNote)) {
    fail(
      'TIER_NOTE_SELF_REFERENCE',
      `the tier note says "${tierNote.match(/\b(?:this|the)\s+tier\b/i)[0]}" — nothing on the ` +
        'card names the tier any more, so the phrase points at nothing. Say what the claim ' +
        'IS about this food instead.'
    );
  }

  // The do line a shopper reads is doLines.json's, not the card's own; a card with no entry
  // there (a generated one) renders its own and is skipped.
  const shownDo = doLines[card?.id ?? card?.slug];
  if (tierNote && shownDo && !TIER_NOTE_ORPHANED_PENDING.has(card?.id ?? card?.slug) && tierNoteOrphaned(card, shownDo)) {
    fail(
      'TIER_NOTE_ORPHANED',
      `${card?.id ?? card?.slug}: the tier note was written against the old decision and shares ` +
        `no content word with the do line it sits under — "${shownDo}". Rewrite it to say ` +
        'what kind of claim THAT line is.'
    );
  }

  /* ═══════ `instead` — the free redirect, and the ways it goes wrong ═══════

     THE FIELD EXISTS BECAUSE THE REDIRECT WAS PAID. It lived in `watch_out`, so the shopper
     who could not afford the standard was the one who could not read what to buy instead.
     Moving it free fixes that and opens two new failure modes, both of which this catches,
     because a dedicated field is the likeliest place for each of them to appear.

     ⚠️ ONE: IT NAMES A LESSER VERSION OF THE SAME THING. That is the defect the field was
     built to end — "if it is farmed or nothing, buy the farmed" lowers the bar rather than
     redirecting, and by the salmon card's own argument farmed Atlantic is a different
     product. An `instead` names a DIFFERENT thing: sardines, canned wild, mackerel.
     Detected structurally rather than by vocabulary: if the redirect leads with a hedge, or
     repeats the subject the headline already rejected, it is not an instead.

     ⚠️ TWO: IT READS AS CO-EQUAL. VOICE_SPEC names this as the way the rule breaks from the
     other end — the moment the second-best sounds like an equal option, the card has two
     verdicts again and "one verdict per headline" is broken one field down. */
  const instead = String(card?.instead || '').trim();
  if (instead) {
    if (words(instead) > MAX_INSTEAD_WORDS) {
      fail('INSTEAD_TOO_LONG', `${words(instead)}w > ${MAX_INSTEAD_WORDS}: the redirect is one sentence, not a second card`);
    }

    // A conditional opening is the hedge relocated. "If it is farmed or nothing…" is the
    // shape; the redirect states what to buy, it does not negotiate about whether to.
    if (CONDITIONAL.test(instead.split(/[.,;]/)[0] || '')) {
      fail(
        'INSTEAD_HEDGED',
        `the redirect opens on a condition — "${instead.slice(0, 60)}…". Name what to buy instead; ` +
          'the condition ("when the standard is not there") is what the field already means.'
      );
    }

    // CO-EQUAL LANGUAGE. "just as good", "either works", "equally" — each makes the fallback
    // a second verdict, which is the failure VOICE_SPEC warns about by name.
    if (CO_EQUAL.test(instead)) {
      fail(
        'INSTEAD_CO_EQUAL',
        `"${instead.match(CO_EQUAL)[0]}" makes the redirect an equal option. The headline is the ` +
          'answer; this is what to do when the answer is not there.'
      );
    }

    /* ⚠️ THE REDIRECT MAY NOT BE THE THING THE HEADLINE JUST REFUSED. This is the structural
       version of "a different thing, not a lesser version". The salmon headline rejects
       "farmed"; a redirect containing "farmed" is the card disagreeing with itself one field
       apart — which VOICE_SPEC states as the test for whether a fallback clears the floor.
       Compared on DISTINCTIVE words only, so "salmon" appearing in both is fine and
       "farmed" in both is not. */
    const refused = refusedTerms(headline);
    const echoed = refused.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(instead));
    if (echoed.length) {
      fail(
        'INSTEAD_ECHOES_REFUSED',
        `the redirect names ${echoed.map((t) => `"${t}"`).join(', ')}, which the headline rejects. ` +
          'That is a lesser version of the same thing, not an instead.'
      );
    }
  }

