  rassert.deepEqual(rcodes({ why: 'Buy plain — the sweet one is dessert.' }), ['READ_STACKED']);
  rassert.deepEqual(rcodes({ why: 'Buy plain (not sweet), and skip the rest.' }), []);
  rassert.deepEqual(rcodes({ why: 'Buy plain; skip the rest.' }), []);
});
rtest('READ_STACKED: a look_for "Term — meaning" separator clears, a second em-dash fires', () => {
  rassert.deepEqual(rcodes({ look_for: ['Term — meaning.'] }), []);
  rassert.deepEqual(rcodes({ look_for: ['Term — meaning — aside.'] }), ['READ_STACKED']);
});

    if (shared.length) {
      fail(
        'OBSERVABLE_IN_BOTH',
        `${shared.map((t) => `"${t}"`).join(', ')} appears in the headline AND the do line — ` +
          'the headline keeps the verdict, the observable moves down'
      );
    }
  }

  // K13: the aisle-readability bar (VOICE_SPEC "Readable in the aisle") is fail-level for every card.
  for (const f of readability(card)) fail(f.code, f.field ? `${f.field}: ${f.detail}` : f.detail);
  return out;
}

/* ═══════════════════════════ Corpus-level ═══════════════════════════ */

// An em-dash-then-justification clause is a good shape. Half the corpus wearing it is not:
// eighty cards that all sound alike read as generated even when each line is correct. The
// ceiling is the share the 2026-07-31 sweep landed at (20%) plus room to breathe, so
// ordinary authoring does not trip it and a slide back toward a monoculture does.
export const MAX_EMDASH_SHARE = 0.28;

export const hasEmDashJustification = (doLine) => /—/.test(String(doLine || ''));

// The closing construction: whatever follows the last clause break. "— that percentage is
// water" and "— that percentage is brine" are the same line wearing two nouns.
//
// A line with NO clause break has no closing construction, and returns nothing. This
// matters: comparing whole lines instead flagged every pair of cards that talked about
// the same food, because two meat cards naturally share "ground beef" and "chuck". That
// is shared subject matter, not a repeated construction.
//
// Grammar words are KEPT. The defect is a repeated frame — "that percentage is ___" — and
// the frame is made of exactly the words a content-only bag would throw away.
export function closingConstruction(doLine) {
  const s = String(doLine || '').trim();
  if (!/[—:;]|\.\s+\S/.test(s)) return [];
  const tail = s.split(/[—:;]|\.\s+/).pop() || '';
  return tail.toLowerCase().match(/[a-z][a-z-]+/g) || [];
}

// Two closings collide when they OPEN the same way — the shared frame, not the shared
// vocabulary. "that percentage is water" / "that percentage is brine" share three leading
// tokens and differ only in the final noun.
const MIN_SHARED_PREFIX = 2;

export function sharedPrefix(a, b) {
  let i = 0;
  while (i < a.length && i < b.length && a[i] === b[i]) i++;
  return a.slice(0, i);
}

// A prefix of pure grammar ("it should", "and it is") is not a construction anybody
// notices; it has to carry at least one word with content in it.
const isConstruction = (prefix) =>
  prefix.length >= MIN_SHARED_PREFIX &&
  prefix.some((t) => !GRAMMAR.has(t) && !NEUTRAL.has(t) && t.length >= 3);

/**
 * Lint a whole corpus.
 *
 * PROXIMITY RULE: duplication is scored WITHIN a section and never across one. Sections
 * are aisles — nobody reads a label-terms card and a seafood card in the same breath, so
 * a shared construction between them is not repetition anybody can perceive. Scoring it
 * globally produces rewrites that make individual lines worse in exchange for a variety no
 * shopper experiences.
 *
 * @returns {{violations:Array, report:{verbs:Array, emDashShare:number, total:number}}}
 */
export function lintCorpus(cards) {
  const violations = [];
  const list = (cards || []).filter(Boolean);
  const doOf = (c) => String(c?.do ?? c?.do_line ?? '').trim();

  // ── em-dash share ──
  const withEmDash = list.filter((c) => hasEmDashJustification(doOf(c)));
  const share = list.length ? withEmDash.length / list.length : 0;
  if (share > MAX_EMDASH_SHARE) {
    violations.push({
      code: 'EMDASH_SHARE',
      detail:
        `${withEmDash.length}/${list.length} do lines (${Math.round(share * 100)}%) use the ` +
        `em-dash-then-justification shape, over the ${Math.round(MAX_EMDASH_SHARE * 100)}% ceiling`,
    });
  }

  // ── within-section closing duplication ──
  const bySection = new Map();
  for (const c of list) {
    const key = String(c?.section || 'unsectioned');
    if (!bySection.has(key)) bySection.set(key, []);
    bySection.get(key).push(c);
  }
  for (const [section, group] of bySection) {
    for (let i = 0; i < group.length; i++) {
      for (let j = i + 1; j < group.length; j++) {
        const a = closingConstruction(doOf(group[i]));
        const b = closingConstruction(doOf(group[j]));
        if (!a.length || !b.length) continue;
        const prefix = sharedPrefix(a, b);
        if (isConstruction(prefix)) {
          violations.push({
            code: 'CLOSING_DUPLICATE',
            detail:
              `${section}: ${group[i].slug} and ${group[j].slug} close the same way — ` +
              `"${prefix.join(' ')}…" in both ("${a.join(' ')}" / "${b.join(' ')}")`,
          });
        }
      }
    }
  }

  // ── verb distribution: REPORTED, NEVER FAILED ──
  // Twenty-one lines open with "Read" because twenty-one cards are about reading a label,
  // and that is the physical act. Swapping in synonyms to flatten a histogram makes each
  // line less precise and the corpus no less repetitive. Precision beats variety, so this
  // is a number to look at, not a gate.
  const counts = new Map();
  for (const c of list) {
    const v = firstToken(doOf(c));
    if (v) counts.set(v, (counts.get(v) || 0) + 1);
  }
  const verbs = [...counts.entries()].sort((a, b) => b[1] - a[1]).map(([verb, n]) => ({ verb, n }));

  // ── copula abstraction: REPORTED, NEVER FAILED ──
  // Added 2026-08-02 after the monetization copy pass, where `antithesisChime` PASSED a
  // line that was rejected on sight ("The cart is yours. Keeping it is the membership").
  // It fires on a rhetorical shape rather than a checkable fact, which is weaker footing
  // than anything else here, so it reports. Measured at zero across 961 corpus fields on
  // the day it landed — promote it to a violation only if that holds over time.
  const copula = [];
  for (const c of list) {
    for (const [field, text] of Object.entries({
      headline: c?.headline, do: doOf(c), why: c?.why, tier_note: c?.tier_note,
      detail: c?.detail, kristy_take: c?.kristy_take,
    })) {
      if (!text) continue;
      for (const h of copulaAbstraction(text)) {
        copula.push({ slug: c.slug, field, clause: h.clause, noun: h.noun });
      }
    }
  }

  return {
    violations,
    report: { verbs, emDashShare: share, total: list.length, copulaAbstraction: copula },
  };
}

/* ═══════════════ Readable in the aisle (VOICE_SPEC R2–R4) ═══════════════
   Not wired into lintCard yet (K13); K5–K12 rewrite the cards it fires on.
   Thresholds measured 2026-10-06 over the 109 curated cards: headline+do p95 25 / max 25;
   short_answer p50 62 / max 112; sentence p90 23 / p95 27 / max 43.
   IC-1 (2026-10-14): raised to 28 with the 14-word front. */
export const HEADLINE_DO_MAX = 28; // [PLACEHOLDER] IC-1
export const SHORT_ANSWER_MAX = 40;
export const SENTENCE_MAX = 20;
const READ_FIELDS = ['decision', 'short_answer', 'why', 'look_for', 'watch_out', 'pick_steps', 'science'];
// ponytail: short abbreviation list; extend when a real card splits wrong.
const ABBREV = /\b(e\.g|i\.e|vs|oz|lb|lbs|etc|approx|U\.S)\./gi;
const wordCount = (s) => String(s || '').split(/\s+/).filter(Boolean).length;

/** Split on . ! ? followed by whitespace or end; decimals and ABBREV stay whole. */
export function sentences(text) {
  return String(text || '')
    .replace(ABBREV, (m) => m.replace(/\./g, '\u0000'))
    .split(/(?<=[.!?])\s+/)
    .map((s) => s.replace(/\u0000/g, '.').trim())
    .filter(Boolean);
}

/** Readability findings, same {code, field, detail} shape as voiceTics. Empty is the passing state. */
export function readability(card) {
  const out = [];
  const id = card?.id ?? card?.slug;
  const headline = card?.decision ?? card?.headline;
  const doLine = doLines[id] ?? card?.do ?? card?.do_line;
  const hd = wordCount(headline) + wordCount(doLine);
  if (hd > HEADLINE_DO_MAX) {
    out.push({ code: 'READ_FIVE_SECONDS', field: 'decision', detail: `headline + do line run ${hd} words; the bar is ${HEADLINE_DO_MAX}` });
  }
  const sa = wordCount(card?.short_answer);
  if (sa > SHORT_ANSWER_MAX) {
    out.push({ code: 'READ_FIVE_SECONDS', field: 'short_answer', detail: `${sa} words; the bar is ${SHORT_ANSWER_MAX}` });
  }
  for (const field of READ_FIELDS) {
    const v = field === 'look_for' ? (card?.look_for ?? card?.buying_tips)
      : field === 'decision' ? (card?.decision ?? card?.headline)
      : card?.[field];
    if (v == null) continue;
    for (const raw of [].concat(v)) {
      // look_for entries project labels_decoded as "Term — meaning": that one leading
      // separator is not an aside. Drop the term; a second em-dash still fires.
      const text = field === 'look_for' && typeof raw === 'string' ? raw.replace(/^[^—]*? — /, '') : raw;
      for (const s of sentences(text)) {
        const n = wordCount(s);
        if (n > SENTENCE_MAX) {
          out.push({ code: 'READ_SENTENCE_LONG', field, detail: `${n} words; the bar is ${SENTENCE_MAX}: "${s}"` });
        }
        const stacked = (s.match(/;/g) || []).length + (s.match(/\(/g) || []).length;
        if (s.includes('—')) out.push({ code: 'READ_STACKED', field, detail: `em-dash aside: "${s}"` });
        else if (stacked > 1) out.push({ code: 'READ_STACKED', field, detail: `${stacked} semicolons/parentheticals in one sentence: "${s}"` });
      }
    }
  }
  return out;
}

/* ═══════════════ KTIGHT: pick_steps + science ═══════════════
   The shelf-readable pick (1-3 steps) and one paragraph of why. Not wired into lintCard:
   presence is the ratchet ledger's job (test/ktight.test.js), so a card with neither field
   passes here. */
export const MAX_STEP_WORDS = MAX_DO_WORDS;
export const MAX_SCIENCE_WORDS = 70;
const REDIRECT = [
  /\b(spend|save|put)\b[^.]{0,40}\b(money|budget)\b/i,
  /\b(money|budget)\b[^.]{0,30}\b(elsewhere|instead|toward|towards)\b/i,
];

/** Lint the KTIGHT fields of one question entry. Empty is the passing state. */
export function lintPickSteps(entry) {
  const out = [];
  const e = entry || {};
  const hasSteps = 'pick_steps' in e;
  const hasScience = 'science' in e;
  if (!hasSteps && !hasScience) return out;
  const fail = (code, detail) => out.push({ code, detail });
  const texts = [];

  if (hasSteps) {
    const steps = e.pick_steps;
    if (!Array.isArray(steps) || steps.length < 1 || steps.length > 3 || steps.some((s) => typeof s !== 'string')) {
      fail('STEPS_SHAPE', 'pick_steps is a string[] of 1-3 lines');
    } else {
      const doLine = normText(doLines[e.id]);
      for (const step of steps) {
        if (!step.trim()) { fail('STEPS_EMPTY', 'a blank step'); continue; }
        texts.push(step);
        if (words(step) > MAX_STEP_WORDS) fail('STEPS_TOO_LONG', `${words(step)}w > ${MAX_STEP_WORDS}: "${step}"`);
        if (!/\.$/.test(step.trim()) || step.includes('?')) fail('STEPS_NOT_CLOSED', `a step ends in "." and never asks: "${step}"`);
        if (doLine && normText(step) === doLine) fail('STEPS_COPIES_DO', `a step may extend the do line, never copy it: "${step}"`);
      }
    }
  }

  if (hasScience) {
    const sci = e.science;
    if (typeof sci !== 'string' || !sci.trim()) {
      fail('SCIENCE_SHAPE', 'science is one non-empty string');
    } else {
      texts.push(sci);
      if (/\n/.test(sci) || /^\s*([-•*]|\d+[.)])\s/.test(sci)) fail('SCIENCE_NOT_PARAGRAPH', 'science is one paragraph, no newline or list marker');
      if (words(sci) > MAX_SCIENCE_WORDS) fail('SCIENCE_TOO_LONG', `${words(sci)}w > ${MAX_SCIENCE_WORDS}`);
    }
  }

  const { pick_steps: _s, science: _c, ...rest } = e;
  const known = new Set(JSON.stringify(rest).match(/\d+/g) || []);
  for (const t of texts) {
    if (hasFirstPerson(t)) fail('KT_FIRST_PERSON', `no I/me/my/we/our: "${t}"`);
    if (t.includes('—')) fail('KT_EM_DASH', `no em-dash asides: "${t}"`);
    for (const n of t.match(/\d+/g) || []) {
      if (!known.has(n)) fail('KT_NEW_NUMBER', `"${n}" appears nowhere else in the entry: "${t}"`);
    }
    if (REDIRECT.some((re) => re.test(t))) fail('KT_REDIRECT', `no money redirect: "${t}"`);
    for (const b of britishSpellings(t)) fail('COPY_BRITISH', `American spelling: "${b}"`);
    if (STRAIGHT_QUOTE.test(t)) fail('COPY_STRAIGHT_QUOTE', `typographic quotes only: "${t}"`);
  }
  const steps = Array.isArray(e.pick_steps) ? e.pick_steps.filter((s) => typeof s === 'string') : [];
  const science = typeof e.science === 'string' ? e.science : '';
  // Allowlisted sentences still run the lock; only their CLAIM_TREATMENT finding is dropped.
  const allowed = (s) => PRESERVATION_CURE_SENTENCES.has(s);
  const unlisted = (t) => sentences(t).filter((s) => !allowed(s)).join(' ');
  const exempt = [...steps, science].flatMap(sentences).filter(allowed);
  const hits = [
    ...claimLockViolations({ look_for: steps.map(unlisted), detail: unlisted(science) }),
    ...claimLockViolations({ look_for: exempt, detail: '' }).filter((v) => v.code !== 'CLAIM_TREATMENT'),
  ];
  for (const v of hits) fail(`KT_${v.code}`, v.detail);
  return out;
}

// INVARIANT: each sentence reviewed as preservation sense; adding one is a reviewed corpus change, never a regex.
// Exact pick_steps/science sentences (as split by sentences()) whose meat-cure wording trips the claim lock's
// treatment rule. Any other sentence, including a near-miss of one of these, reads the raw lock. Fail-closed.
export const PRESERVATION_CURE_SENTENCES = Object.freeze(new Set([
  "Read the ingredients list; every curing substance has to be named there.",
  "‘Uncured’ meat is cured, using celery powder instead of added nitrite.",
  "Celery powder is a concentrated natural nitrate source, so it is a curing agent, not the absence of one.",
  "Read each curing ingredient, including salt, sugar and curing agents.",
  "Compare the disclosed curing ingredients across the bacon packs on the shelf.",
  "Bacon labeled uncured can use celery powder as a natural curing source.",
  "US curing-label policy requires curing-mixture ingredients to be listed individually.",
  "The curing ingredients describe the process.",
  "The source set does not establish a health advantage from choosing celery-based curing.",
  "“Uncured” can still mean celery-based curing; read the qualifier.",
  "Ham is the cured leg of pork, and its product name tells how much water the curing added.",
  "Read each curing ingredient in the ingredients statement.",
  "Under US labeling, “bacon” alone means cured pork belly.",
  "Turkey bacon is still a cured product.",
  "Each substance in a curing mixture, such as salt, sugar, or sodium nitrite, must be listed.",
  "Each of these is pork cured with salt and curing agents.",
  "Prosciutto is dry-cured raw ham, not smoked; its low water content lets it be eaten raw.",
  "Salami is a fermented, dried and cured ground product.",
  "Pancetta is cured belly, and cheek meat must carry its true name, such as pork jowl.",
]));

/* ═══════════════════════════ Health first (chf-1) ═══════════════════════════ */

// EVERY CARD AIMS AT THE CLOSEST-TO-NATURE VERSION, NOT THE COOK (Devon 2026-10-12). "80/20
// for burgers" picks for the pan; the card picks for the body. And a health fact shared by a
// family lives on ONE owner card; siblings carry a pointer step `<Read>: see <Owner title>.`
// Plan: docs/plans/card-health-first-plan.md ("One fact, one owner", Piece 1). Not wired into
// `lintCard`; the corpus test holds curated cards to it, with the cards that fail today
// listed below until later pieces empty the list.
export const HEALTH_FIRST_PENDING = new Set([]);

// Word-bounded, so `tender` never matches `tenderized` (a safety fact, not a cook's aim).
export const CULINARY_LEXICON =
  /\b(for burgers?|braise|braising|sear|searing|grill|grilling|bake|baking|roast|roasting|stew|stewing|recipe|crispy|chew|chewy|tender|tenderness|flavou?r|taste|melt|melts|melting|juicy)\b/i;
// Food safety is not cooking advice: a sentence naming a temperature or a spoilage sign stands.
// Bare `crisp` is a produce freshness sign, and ingredient/label names (baking soda, natural flavors) are not an aim.
export const CULINARY_SAFETY_ALLOW =
  /°F|internal temperature|spoil|slime|off smell|sour smell|use-by|sell-by|use by|sell by|baking (soda|powder)|(natural|artificial) flavou?rs?|flavou?r claim/i;

const sentencesOf = (s) => String(s || '').split(/(?<=[.!?])\s+/).filter((x) => x.trim());

export function lintCulinaryAim(entry) {
  const out = [];
  const scan = (field, text) => {
    for (const s of sentencesOf(text)) {
      if (CULINARY_LEXICON.test(s) && !CULINARY_SAFETY_ALLOW.test(s)) out.push({ code: 'CULINARY_AIM', field, text: s });
    }
  };
  if (typeof entry?.decision === 'string') scan('decision', entry.decision);
  if (typeof entry?.cart_pick === 'string') scan('cart_pick', entry.cart_pick);
  for (const step of Array.isArray(entry?.pick_steps) ? entry.pick_steps : []) {
    if (typeof step === 'string') scan('pick_steps', step);
  }
  return out;
}

/* The list→card match probe. Measures CORRECTNESS, and exits non-zero on a wrong match.
 *
 *   node scripts/listMatchProbe.js
 *
 * ═══ WHAT THE FIRST VERSION MEASURED, AND WHY THE NUMBER WAS HOLLOW ═══
 *
 * The Phase 1 probe reported 71%→83% coverage with ZERO false positives, and both figures
 * were true of what it asked. It asked the wrong thing, twice:
 *
 *   1. ITS FAILURE CLASS WAS ONLY "MATCHED SOMETHING WHEN IT SHOULD HAVE MATCHED NOTHING."
 *      Six items — cereal, dish soap, paper towels, ketchup, pasta sauce, tortillas — were
 *      marked `expect: 'none'`, and a hit on one of those was the only thing counted as a
 *      false positive. Everything else was scored `hit ? pass : miss`. An item that matched
 *      the WRONG CARD counted as a SUCCESS. "Frozen broccoli or green beans" landing on
 *      `beans_dried_vs_canned` — "fill a bag from the bulk bin" on a frozen item — would
 *      have been tallied as one of the 83%.
 *
 *   2. ITS INPUT WAS BARE NOUNS IT INVENTED. Thirty lowercase singles and pairs
 *      ("blueberries", "chicken thighs"), which is what a shopper TYPES. It is not what the
 *      compose flow EMITS: composed rows carry authored PICK names ("Frozen broccoli or
 *      green beans"), a `why` on all 51, and an authored `perimeterId` on 22.
 *
 * So the probe agreed with the mock, which agreed with the harness, which agreed with the
 * browser test — and none of them agreed with the product.
 *
 * ═══ WHAT THIS MEASURES INSTEAD ═══
 *
 * Ground truth, two sources, no hand-maintained expectation list:
 *
 *   AUTHORED   the 22 PICKS carrying a `perimeterId`. That id was chosen by a person and is
 *              claim-locked. Retrieval disagreeing with it is a WRONG MATCH, not a hit.
 *   OVERLAP    for a card reached by retrieval with no authored id, the card must share a
 *              real food word with the item. Zero food overlap is the shape every false
 *              positive in this class has taken — "tuna" reaching a fresh-counter card,
 *              "beans" reaching a dried-beans card, "unpasteurized" reaching a milk card,
 *              and "worth"/"buying" reaching a farmed-fish card in the ask pipeline.
 *
 *   STATE      an item that names canned / tinned / dried attached to a PRODUCE card whose own
 *              text names no state is WRONG. The produce section sells the fresh thing, so a
 *              stateless produce card is about the fresh thing (`cardStates`, listMatch.js),
 *              and "Canned tomatoes" → `produce_ripeness_by_item` told a shopper to smell the
 *              stem end of a tin (API-FINDINGS §17). The probe reads the card's text with the
 *              same STATES regexes and never the matcher's inference — a probe that asks the
 *              matcher whether the matcher is right proves nothing.
 *
 * ═══ TWO POPULATIONS, BECAUSE THE FIRST ONE COVERED THE DOOR NOBODY WALKS THROUGH FIRST ═══
 *
 * Moving off invented bare nouns onto PICKS fixed one blindness by creating another. PICKS
 * are the SEEDED path, where an authored `perimeterId` attaches regardless of aliases. The
 * BUILD path — the one every new shopper takes — has the model emit bare nouns and retrieval
 * is all there is, and this probe was green (37/37, 0 wrong) while five of the first walk's
 * eight rows attached nothing (API-FINDINGS §16, WALK-2026-09-10 W16). So BARE_NOUNS is the
 * second population: what a shopper TYPES, judged by the same two wrong-match rules.
 *
 * A MISS IS REPORTED AND DOES NOT FAIL. Coverage is an authoring backlog — that is what
 * `counter_gaps` is for. A WRONG MATCH FAILS, because a wrong do line is worse than no do
 * line and is the only outcome here that actively misinforms someone in a store.
 */

import { PICKS } from '../lib/list.js';
import { attachCards, cardForItem, entryById, matchItemToCard, matchItemToPick, STATES } from '../lib/listMatch.js';
import { sectionForCategory } from '../lib/counterCards.js';
import { scoreEntries } from '../lib/perimeter.js';

/* Words that describe a STATE, a QUALITY or a package rather than a food. A card sharing
   only these with an item has not matched its subject — which is the whole failure mode. */
const NOT_A_FOOD = new Set([
  'and', 'the', 'for', 'with', 'from', 'any', 'two', 'kinds', 'whatever', 'own',
  'raw', 'plain', 'whole', 'real', 'fresh', 'frozen', 'canned', 'dried', 'dry', 'tinned',
  'ground', 'roasted', 'baby', 'sweet', 'steel', 'cut', 'live', 'culture', 'cultures',
  'grass', 'fed', 'pasture', 'raised', 'wild', 'caught', 'bone', 'bones', 'boneless',
  'unpasteurized', 'pasteurized', 'refrigerated', 'sprouted', 'extra', 'virgin', 'dark',
  'bottle', 'low', 'sugar', 'free', 'salt', 'just', 'season', 'lean', 'light', 'white',
  'best', 'buy', 'buying', 'worth', 'good', 'better', 'vs', 'versus', 'what', 'which',
  'grade', 'grades', 'label', 'labels', 'labeled', 'check', 'read', 'pick', 'picking',
]);

const words = (s) =>
  new Set(
    String(s || '')
      .toLowerCase()
      .match(/[a-z]+/g)
      ?.filter((w) => w.length > 2 && !NOT_A_FOOD.has(w)) || []
  );

const pad = (s, n) => String(s ?? '').padEnd(n);

/* ═══ --universe <path>: K2 coverage over the whole-store universe ═══
   Each row goes through the real attach path (card first, then pick floor). Covered = a card
   or pick attached. `carried` rows are counted apart and are never gaps. Exit 1 only when a
   row's `expect` id is set and a different id attached. Default mode below is untouched. */
const uIdx = process.argv.indexOf('--universe');
if (uIdx > -1) {
  const { readFileSync } = await import('node:fs');
  const path = process.argv[uIdx + 1];
  if (!path) { console.error('--universe needs a path'); process.exit(1); }
  const universe = JSON.parse(readFileSync(path, 'utf8'));
  if (!Array.isArray(universe) || universe.length < 1) { console.error('universe is empty'); process.exit(1); }
  const sections = new Map();
  const carried = [];
  const gaps = [];
  const wrongs = [];
  const missing = [];
  let hasWords = false;
  const attachId = (name) => {
    const r = attachCards({ items: [{ name, source: 'user' }] }, { log: false }).items[0];
    return r.cardSlug || r.pickId || null;
  };
  for (const u of universe) {
    let got;
    if (Array.isArray(u.list_words) && u.list_words.length) {
      hasWords = true;
      let all = true;
