    sections: ['bulk_pantry', 'frozen', 'eggs_dairy'], categories: null,
    gloss: 'sunflower, safflower, canola, soybean, corn, and cottonseed',
    trace: 'engine KB seed_oil entry names (S9)',
  },
];

// [PLACEHOLDER] lexical budgets from docs/CARD-ALIGNMENT-PLAN.md CA-1.
const STOPWORDS = new Set(('a an the and or of to in on for with from at by is are was were be it its ' +
  'this that these those as not no nor but if so than then there their they them what how when where ' +
  'which who your you any each all more most some such into out up over only also can will has have had do does').split(' '));
const HANDLING = /\b(?:seal(?:ed)?\b|leak|smell|odou?r|colou?r|cold\b|temperature|sell-by|use-by|expir|dent(?:ed|s)?\b|bulg|bruis|wash|stor(?:e|ed|age)\b|fridge)/i;
const FAMILIES = [/grass[- ]?(?:fed|finished)/i, /pasture[- ]raised/i, /\borganic\b/i, /wild[- ]caught/i];
const FIRST_RUNG_SPLIT = /\s+first\b|,\s*then\b|;\s*then\b|\bnever\b/i;
const SECTION_TIP_N = 5;
const SECTION_FIELDS_N = 6;
const SECTION_FRONT_N = 4;
const SECTION_REPEAT_CARDS = 3;

const norm = (s) => String(s).toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"');
const sectionCardStrings = (texts) => texts.filter((s) => typeof s === 'string' && s.trim() && !POINTER.test(s));

// Cut the union of canonical spans, keeping the pieces separate so a phrase cannot
// bridge over an exempt term or gloss. Repetition exemptions deliberately ignore scope.
function sectionSegments(raw) {
  const text = norm(raw);
  const spans = [];
  for (const row of CANONICAL_GLOSSES) {
    for (const m of text.matchAll(new RegExp(row.term.source, `${row.term.flags}g`))) {
      spans.push([m.index, m.index + m[0].length]);
    }
    const gloss = norm(row.gloss);
    for (let start = text.indexOf(gloss); start !== -1; start = text.indexOf(gloss, start + 1)) {
      spans.push([start, start + gloss.length]);
    }
  }
  spans.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const segments = [];
  let end = 0;
  for (const [start, stop] of spans) {
    if (start > end) segments.push(text.slice(end, start));
    end = Math.max(end, stop);
  }
  if (end < text.length) segments.push(text.slice(end));
  return segments;
}

function* sectionNgrams(texts, n) {
  for (const text of texts) {
    for (const segment of sectionSegments(text)) {
      const tokens = segment.match(/[a-z0-9%']+/g) || [];
      for (let i = 0; i + n <= tokens.length; i++) {
        const gram = tokens.slice(i, i + n);
        if (gram.filter((token) => !STOPWORDS.has(token)).length >= 2) yield gram.join(' ');
      }
    }
  }
}

// Resolve only the card's scoped rows. Longer matches consume their spans before
// shorter matches, but emitted rows always retain canonical table order.
function resolveSectionTerms(raw, section, category) {
  const text = norm(raw);
  const matches = [];
  CANONICAL_GLOSSES.forEach((row, index) => {
    if (!row.sections.includes(section) || (row.categories !== null && !row.categories.includes(category))) return;
    for (const m of text.matchAll(new RegExp(row.term.source, `${row.term.flags}g`))) {
      matches.push({ index, start: m.index, end: m.index + m[0].length });
    }
  });
  matches.sort((a, b) => (b.end - b.start) - (a.end - a.start) || a.start - b.start || a.index - b.index);
  const accepted = [];
  for (const match of matches) {
    if (!accepted.some((other) => match.start < other.end && other.start < match.end)) accepted.push(match);
  }
  const indices = new Set(accepted.map((match) => match.index));
  return CANONICAL_GLOSSES.filter((row, index) => indices.has(index));
}

/** Pure, opt-in section checks. Existing card and corpus lints stay independent. */
export function lintSections(tips, entries) {
  const out = [];
  for (const row of tips) {
    const tipOn = row.tip_aligned === true;
    const cardsOn = row.cards_aligned === true;
    if (!tipOn && !cardsOn) continue;
    const section = row.section;
    const cards = entries.filter((entry) => {
      const home = sectionForCategory(entry.category);
      return home !== null && home === section;
    });
    const tipStrings = [row.rule, ...(row.checks || [])].filter((s) => typeof s === 'string' && s.trim());
    const fields = cards.map((entry) => sectionCardStrings(REPEATED_CLAIM_FIELDS.flatMap((f) => stringsIn(entry[f]))));

    // L1: the first shared phrase in tip order gives at most one hit per card.
    if (tipOn) {
      const tipKeys = [...sectionNgrams(tipStrings, SECTION_TIP_N)];
      cards.forEach((entry, index) => {
        const texts = [...sectionCardStrings([entry.decision]), ...fields[index]];
        const keys = new Set(sectionNgrams(texts, SECTION_TIP_N));
        const phrase = tipKeys.find((key) => keys.has(key));
        if (phrase) out.push({ code: 'SECTION_TIP_REPEATS_CARD', section, id: entry.id, phrase });
      });
    }

    // L2: each card contributes once per phrase; equal id lists share one hit.
    if (cardsOn) {
      for (const [form, n] of [['fields', SECTION_FIELDS_N], ['front', SECTION_FRONT_N]]) {
        const holders = new Map();
        cards.forEach((entry, index) => {
          const texts = form === 'fields' ? fields[index] : sectionCardStrings([entry.decision, entry.tier_note]);
          for (const key of new Set(sectionNgrams(texts, n))) {
            if (!holders.has(key)) holders.set(key, []);
            holders.get(key).push(entry.id);
          }
        });
        const groups = new Set();
        for (const [phrase, heldBy] of holders) {
          if (heldBy.length < SECTION_REPEAT_CARDS) continue;
          const ids = [...heldBy].sort();
          const group = JSON.stringify(ids);
          if (groups.has(group)) continue;
          groups.add(group);
          out.push({ code: 'SECTION_PHRASE_REPEATED', section, form, ids, phrase });
        }
      }
    }

    // L3: preserve the raw tip text for review.
    if (tipOn) {
      for (const text of tipStrings) {
        if (HANDLING.test(text)) out.push({ code: 'SECTION_TIP_HANDLING', section, text });
      }
    }

    if (cardsOn) {
      // L4: a front's term needs its own gloss on this card, in one allowed string.
      for (const entry of cards) {
        const glossTexts = ['tier_note', 'pick_steps', 'instead'].flatMap((f) => stringsIn(entry[f])).map(norm);
        for (const termRow of resolveSectionTerms(entry.decision, section, entry.category)) {
          if (!glossTexts.some((text) => text.includes(norm(termRow.gloss)))) {
            out.push({ code: 'TERM_UNGLOSSED', section, id: entry.id, row: termRow.id });
          }
        }
      }

      // L5: keep each cart pick within the front's families and first-rung terms.
      for (const entry of cards) {
        const pick = entry.cart_pick;
        if (typeof pick !== 'string' || !pick.trim()) continue;
        const decision = String(entry.decision ?? '');
        if (FAMILIES.some((family) => family.test(pick) && !family.test(decision))) {
          out.push({ code: 'CART_PICK_DISAGREES', section, id: entry.id, form: 'a' });
        }
        const rung = decision.split(FIRST_RUNG_SPLIT)[0];
        if (resolveSectionTerms(rung, section, entry.category).some((termRow) =>
          !termRow.term.test(pick) && !norm(pick).includes(norm(termRow.gloss)))) {
          out.push({ code: 'CART_PICK_DISAGREES', section, id: entry.id, form: 'b' });
        }
      }
    }
  }
  return out;
}
","server/lib/counterCardLint.test.js":"// Counter card lint — the shape bar, enforced. NO network, NO model, NO database.
//
// Every rule here is a defect that was found by hand on 2026-07-31 during the Pass 2
// review sweep. The point of the file is that none of them can come back silently —
// least of all through a card Pass 3 GENERATES, which renders in the same component as a
// curated one and therefore has to clear the same bar. So the rules are tested twice:
// against synthetic generated cards (the unit tests) and against all 80 curated cards
// (the corpus tests).

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { nonEmpty } from './testGuards.js';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import perimeterKb from '../kristy_perimeter_kb.json' with { type: 'json' };
import { projectEntry, parseReviewTable, RETIRED, RETIRED_GENERATED } from './counterCards.js';
import { PERIMETER_SECTIONS, questionEntries } from './perimeter.js';
import { DEPTH_FIELDS } from './counterCards.js';
import {
  lintCard,
  lintPick,
  lintCorpus,
  mechanicalVeto,
  MECHANICAL_VETO,
  MAX_PICK_WORDS,
  PICK_FORBIDDEN_FIELDS,
  headlineHedge,
  falseMechanisms,
  contradictions,
  sharedObservables,
  closingConstruction,
  copulaAbstraction,
  antithesisChime,
  words,
  firstToken,
  IMPERATIVE_VERBS,
  MAX_DO_WORDS,
  MAX_HEADLINE_WORDS,
  MAX_EMDASH_SHARE,
  tierNoteOrphaned,
  TIER_NOTE_ORPHANED_PENDING,
  lintSections,
} from './counterCardLint.js';
import doLines from './doLines.json' with { type: 'json' };
import sectionRules from './sectionRules.json' with { type: 'json' };

const __dirname = dirname(fileURLToPath(import.meta.url));
const REVIEW_FILE = join(__dirname, '..', '..', 'docs', 'do-lines-review.md');

/* ═══════════════════════════ The curated corpus ═══════════════════════════ */

const reviewed = nonEmpty(parseReviewTable(readFileSync(REVIEW_FILE, 'utf8')), 'the reviewed do-line table');
// QUESTION ENTRIES ONLY: a pick (`kind: 'pick'`) is linted by `lintPick`, never projected
// into a card, and holding it to the card's bar would fail it for lacking a headline.
const CARDS = nonEmpty(
  questionEntries().map((e) => projectEntry(e, { doLine: reviewed.get(e.id)?.do || '' })),
  'the projected card corpus'
);

const codes = (violations) => violations.map((v) => v.code);

// A generated card is a plain object in the same shape — this is what Pass 3 will hand
// the lint before persisting anything.
const generated = (over = {}) => ({
  slug: 'generated_test',
  section: 'produce',
  source: 'generated',
  headline: 'Buy the loose ones and skip the bag.',
  do: 'Squeeze the stem end; it should give slightly.',
  ...over,
});

/* ═══════════════════════════ Length and imperative ═══════════════════════════ */

test('a do line over 14 words fails, on a generated card', () => {
  const card = generated({
    do: 'Read the label on the package and then check the second panel for the added sugars line as well.',
  });
  assert.ok(words(card.do) > MAX_DO_WORDS);
  assert.ok(codes(lintCard(card)).includes('DO_TOO_LONG'));
});

test('a headline over 14 words fails, on a generated card', () => {
  const card = generated({
    headline: 'This is a description of the produce section that runs on well past the limit.',
  });
  assert.ok(words(card.headline) > MAX_HEADLINE_WORDS);
  assert.ok(codes(lintCard(card)).includes('HEADLINE_TOO_LONG'));
});

test('a do line that describes instead of instructing fails', () => {
  // The failure this exists to catch: a generated line that reads like prose.
  const card = generated({ do: 'Organic is generally the better choice in this aisle.' });
  assert.ok(codes(lintCard(card)).includes('DO_NOT_IMPERATIVE'));
});

test('a missing do line fails — a card with no action is not a card', () => {
  assert.ok(codes(lintCard(generated({ do: '' }))).includes('DO_MISSING'));
});

test('hyphenated compounds count as one word', () => {
  // "grass-finished" is one thing a shopper looks for. Splitting it would make the
  // 14-word bar punish precision.
  assert.equal(words('Buy grass-finished, not grass-fed.'), 4);
});

/* ═══════════════════════════ Ruling 4 — the observable ═══════════════════════════ */

test('ruling 4: a quoted observable in BOTH the headline and the do line fails', () => {
  // The real historical defect, verbatim: egg_feed_claims before 2026-07-31.
  const shared = sharedObservables(
    'Feed claims have to be printed. Look for soy-free.',
    'Look for “soy-free” printed explicitly — no other carton word implies it.'
  );
  assert.deepEqual(shared, ['soy-free']);
  assert.ok(codes(lintCard(generated({
    headline: 'Feed claims have to be printed. Look for soy-free.',
    do: 'Look for “soy-free” printed explicitly — no other carton word implies it.',
  }))).includes('OBSERVABLE_IN_BOTH'));
});

test('ruling 4: flour_basics, the same defect without quotes on the headline side', () => {
  assert.deepEqual(
    sharedObservables(
      'Unbleached all-purpose. Keep whole wheat in the freezer.',
      'Read for “unbleached” — “bleached” was chemically whitened.'
    ),
    ['unbleached']
  );
});

test('ruling 4: TWO shared terms fail even when neither is quoted', () => {
  // A line orbiting its own headline rather than adding to it.
  const shared = sharedObservables(
    'Plain oats, any form. Skip the flavored instant packets.',
    'Pass the flavored instant boxes. Plain oats list one ingredient.'
  );
  assert.deepEqual(shared.sort(), ['flavored', 'instant']);
});

test('ONE shared subject noun is fine — the do line still earns its place', () => {
  // A card about grass-fed beef says "grass-fed" twice and is correct: the do line adds
  // the cut. Flagging this would make the check useless.
  assert.deepEqual(
    sharedObservables(
      'Grass-fed and grass-finished. Grass-fed alone is still a feedlot finish.',
      'Buy grass-fed as ground beef or chuck, not as ribeye.'
    ),
    []
  );
});

test('a quoted QUESTION is speech, not a printed observable', () => {
  // "was this previously frozen?" is said out loud at the counter. Counting it as a
  // printed word flagged a card that was correct.
  assert.deepEqual(
    sharedObservables(
      'Buy the frozen. Thaw it overnight in the fridge.',
      'Ask the counter “was this previously frozen?” before paying the fresh premium.'
    ),
    []
  );
});

/* ═══════════════════════════ Corpus shape ═══════════════════════════ */

test('the em-dash-then-justification share stays under the ceiling', () => {
  const { report, violations } = lintCorpus(CARDS);
  assert.ok(
    report.emDashShare <= MAX_EMDASH_SHARE,
