import assert from 'node:assert/strict';
import { lintSections, CANONICAL_GLOSSES } from './server/lib/counterCardLint.js';
import { assertPassRule } from './server/test/acceptance/passRule.js';
const freeze = (v) => { if (v && typeof v === 'object') { Object.values(v).forEach(freeze); Object.freeze(v); } return v; };
const repeated = (cards) => lintSections([{ section: 'meat', cards_aligned: true }], cards).filter(h => h.code === 'SECTION_PHRASE_REPEATED');
const plain = (id, why) => ({ id, category: 'beef', decision: 'Fixture', why });
const phrase = 'amber birch cedar dogwood elm fir';
const cards = freeze([plain('z', [phrase, phrase]), plain('a', phrase), { ...plain('m', phrase), kind: 'pick' }]);
assert.deepEqual(repeated(cards), [{ code: 'SECTION_PHRASE_REPEATED', section: 'meat', form: 'fields', ids: ['a', 'm', 'z'], phrase }]);
assert.deepEqual(repeated(cards.slice(0,2)), []);
assert.deepEqual(repeated(['a','b','c'].map(id => plain(id, 'amber birch cedar organic dogwood elm fir'))), []);
assert.deepEqual(repeated(['a','b','c'].map(id => plain(id, 'amber birch cedar tallow, olive oil, or coconut oil dogwood elm fir'))), []);
const tip = freeze([{ section: 'meat', tip_aligned: true, rule: 'cedar dogwood elm fir hazel; amber birch cedar dogwood elm', checks: [] }]);
assert.deepEqual(lintSections(tip, freeze([plain('z', 'amber birch cedar dogwood elm fir hazel')])), [{ code: 'SECTION_TIP_REPEATS_CARD', section: 'meat', id: 'z', phrase: 'cedar dogwood elm fir hazel' }]);
assert.deepEqual(lintSections([{ section: null, tip_aligned: true, cards_aligned: true }], [{ id: 'unknown', category: 'no_such_section', decision: 'Organic beef', cart_pick: 'Grass-fed beef' }]), []);
const gloss = CANONICAL_GLOSSES[0].gloss.replace(/[‘’]/g, \"'\").replace(/[“”]/g, '\"').toUpperCase();
assert.deepEqual(lintSections(freeze([{ section: 'meat', cards_aligned: true }]), freeze([{ id: 'quoted', category: 'beef', decision: '100% grass-fed or grass-finished beef', pick_steps: { nested: [gloss] } }])), []);
const ordered = lintSections([{ section: 'meat', cards_aligned: true }], [{ id:'terms', category:'beef', decision:'Organic, pasture-raised, 100% grass-fed or grass-finished beef; organic beef' }]);
assert.deepEqual(ordered.map(h => h.row), ['G1', 'G3', 'G4']);
const old = { id:'organ_meats', decision:'Buy 12 ounces.', why:'Old why.', watch_out:['One.', 'Two.'], labels_decoded:[{term:'Liver', meaning:'Old meaning.'}], aliases:['liver'], asked_as:['which liver'], sources:['https://example.org/source'] };
assert.throws(() => assertPassRule(null, old, {...old, decision:'Buy organs.'}));
assert.throws(() => assertPassRule(null, old, {...old, why:''}));
assert.throws(() => assertPassRule(null, old, {...old, watch_out:['One.']}));
assert.throws(() => assertPassRule(null, old, {...old, labels_decoded:[{term:'Heart', meaning:'New meaning.'}]}));
assert.throws(() => assertPassRule(null, old, {...old, asked_as:[]}));
assert.doesNotThrow(() => assertPassRule(null, {id:'outside', decision:'Old front'}, {id:'outside', decision:'New front'}));
console.log('Additional checks passed: frozen input purity, picks included, per-card deduplication, segment boundaries, first tip phrase, unmapped categories, normalized/nested glosses, row order/deduplication, and passRule preservation.');
JS"

